using System.Collections.Generic; using System.Linq; using System.Web; using MyStoreCustomer.Models;
namespace MyStoreCustomer.Services { public static class CartService {private const string Key="CUSTOMER_CART";public static List<CartItem> Get(HttpSessionStateBase s){var c=s[Key] as List<CartItem>;if(c==null){c=new List<CartItem>();s[Key]=c;}return c;}public static void AddOne(HttpSessionStateBase s,Product p){var c=Get(s);var i=c.FirstOrDefault(x=>x.ProductID==p.ProductID);if(i==null)c.Add(new CartItem{ProductID=p.ProductID,ProductName=p.ProductName,UnitPrice=p.ProductPrice,ProductImage=p.ProductImage,Quantity=1});else i.Quantity++;}}}